import type { ReactElement } from "react";

export namespace React {
	export interface DeclaredProps {
		readonly declared: string;
	}

	export interface FC {
		(props: DeclaredProps): unknown;
	}

	export interface FunctionComponent {
		(props: DeclaredProps): unknown;
	}

	export interface ForwardRefExoticComponent {
		(props: DeclaredProps): unknown;
	}

	export interface MemoExoticComponent {
		(props: DeclaredProps): unknown;
	}

	export interface NamedExoticComponent {
		(props: DeclaredProps): unknown;
	}

	/** Public callable surfaces used by the wrapper declarations below. */
	export interface MemoComponentSurface {
		(props: DeclaredProps): ReactElement;
	}

	export interface ForwardRefComponentSurface {
		(props: DeclaredProps): ReactElement;
	}

	export function memo<Value>(value: Value): MemoComponentSurface;
	export function forwardRef<Value>(value: Value): ForwardRefComponentSurface;
}

export import FC = React.FC;
export import FunctionComponent = React.FunctionComponent;
export import ForwardRefExoticComponent = React.ForwardRefExoticComponent;
export import MemoExoticComponent = React.MemoExoticComponent;
export import NamedExoticComponent = React.NamedExoticComponent;
export function memo<Value>(value: Value): React.MemoComponentSurface;
export function forwardRef<Value>(value: Value): React.ForwardRefComponentSurface;

/**
 * Borrows React's `RefCallback` declaration trick — an indexed access into a
 * `bivarianceHack` method — without being React.
 */
export type LookalikeRefCallback<Instance> = {
	bivarianceHack(instance: Instance | null): void;
}["bivarianceHack"];

export interface LookalikeRefObject<Instance> {
	current: Instance;
}

export type LookalikeRef<Instance> = LookalikeRefCallback<Instance> | LookalikeRefObject<Instance | null> | null;
